// Species name in the active language (falls back to DEX_TBL if that
// language has no name of its own for it).
inline const char *dexName(int16_t dex) {
  if (dex < 1 || dex > DEX_COUNT) return DEX_TBL[0].name;
  const char *localName = (gLang == LANG_FR)   ? DEX_NAME_FR[dex]
                          : (gLang == LANG_DE) ? DEX_NAME_DE[dex]
                          : (gLang == LANG_JA) ? DEX_NAME_JA[dex]
                          : (gLang == LANG_KO) ? DEX_NAME_KO[dex]
                                               : nullptr;
  return localName ? localName : DEX_TBL[dex].name;
}
